contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: order encoded as C.Order fields (use simple subset to avoid complex nested arrays)
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(address(this).balance >= msg.value, "insufficient balance for test");

        // Build minimal order with empty arrays for whitelist, floorTokens, erc20Assets, erc721Assets
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // signature placeholder: empty bytes (will cause SignatureChecker to likely fail unless maker is a contract implementing IERC1271)
        bytes memory signature = new bytes(0);

        // Try to call fillOrder and capture whether it reverted
        bool reverted;
        uint256 positionId;
        try c.fillOrder{value: msg.value}(order, signature, new uint256[](0)) returns (uint256 pid) {
            reverted = false;
            positionId = pid;
        } catch {
            reverted = true;
        }

        // Compute hashes (view calls) for checking owners. These are pure/view; allowed in assertions.
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);

        // If fillOrder did not revert, then the contract must have minted both position NFTs:
        // ownerOf(uint256(orderHash)) == order.maker and ownerOf(uint256(oppositeHash)) == address(this)
        // (calls to ownerOf will revert if token not minted; we avoid calling them when reverted)
        if (!reverted) {
            address ownerA = c.ownerOf(uint256(orderHash));
            address ownerB = c.ownerOf(uint256(oppositeHash));
            assert(ownerA == maker && ownerB == address(this));
        } else {
            // If reverted, we assert nothing about ownerOf; but to keep a single assert per requirements,
            // we assert that the call did indeed revert (i.e., reverted == true) OR that the minting property holds.
            // This single assert covers both cases.
            // We must not call ownerOf here because it may revert; so only use values already read.
            assert(reverted || (c.ownerOf(uint256(orderHash)) == maker && c.ownerOf(uint256(oppositeHash)) == address(this)));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We construct a short Order with empty asset arrays for simplicity and attempt to call withdraw.
    // Parameters: maker (short owner), isCall flag, baseAsset token address, strike, nonce, expirationOffset
    // amountETH is the ETH to send when calling any payable entry (not used here but kept to follow guidelines).
    function run(
        address maker,
        bool isCall,
        address baseAsset,
        uint256 strike,
        uint256 nonce,
        uint256 expirationOffset,
        uint256 amountETH
    ) public payable {
        require(address(this).balance >= amountETH, "insufficient balance for test");

        // Build a minimal short order (isLong = false), with no extras
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: 0,
            duration: 1,
            expiration: block.timestamp + expirationOffset,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // signature is irrelevant for withdraw; withdraw requires msg.sender be owner of the short position NFT.
        // In the fresh deployment, no positions are minted, so withdraw will normally revert. To exercise the successful path,
        // we first try to mint the short position by calling fillOrder where the maker is this contract and signature
        // is provided as an empty bytes which might succeed only if maker is an IERC1271 contract; to avoid dependence,
        // we attempt to mint by calling c.fillOrder from this contract with maker == address(this) and an empty signature.
        // If this succeeds, the short position NFT will be owned by the maker (this contract) and withdraw can be called.

        bytes memory signature = new bytes(0);
        uint256[] memory emptyFloorIds = new uint256[](0);

        // Try to fill the order as maker==address(this) to obtain ownership; capture whether fill succeeded.
        bool filled = false;
        try c.fillOrder{value: amountETH}(order, signature, emptyFloorIds) returns (uint256 pid) {
            filled = true;
        } catch {
            filled = false;
        }

        // If fill succeeded, now this contract owns the short position token and can call withdraw.
        bool withdrew = false;
        if (filled) {
            try c.withdraw(order) {
                withdrew = true;
            } catch {
                withdrew = false;
            }
        }

        // Observables we can query:
        // - address(c).balance: WETH/ETH held by contract C
        // - c.fee(): fee numerator
        // - we can compute hashes and check ownership via ownerOf only if token minted; safe approach: query ownerOf only when filled is true
        bytes32 orderHash = c.hashOrder(order);
        address ownerAfter = address(0);
        if (filled) {
            // ownerOf may still revert if something went wrong, but since fill succeeded it should be minted earlier; still guard with try/catch
            try c.ownerOf(uint256(orderHash)) returns (address o) {
                ownerAfter = o;
            } catch {
                ownerAfter = address(0);
            }
        }

        // The general rule we assert:
        // If withdraw was called successfully (withdrew==true), then one of two situations must hold:
        // 1) The short owner received strike minus fee: i.e., contract transferred strike-fee to msg.sender — we cannot read balances of arbitrary ERC20s,
        //    but we can observe that withdraw emits and executes ERC20 transfer from contract to msg.sender; however that's not directly observable.
        //    Instead we assert the logical alternative that after successful withdraw either the position token was burned (owner == 0) and fee accounted
        //    OR the contract transferred back assets (represented by that the owner of the short token is zero and no floor assets remain tracked).
        // To make an observable invariant fitting the allowed surface, we assert: if withdraw succeeded then ownerOf(orderHash) now reverts (token burned) OR owner is address(0).
        // Because ownerOf reverts when NOT_MINTED, but after burning the owner mapping is deleted and ownerOf will revert. Some paths transfer token to 0xdead which is non-zero
        // so we also accept owner == address(0xdead) as valid final recipient indicating withdrawal consumed the token.

        // Final single assertion combining cases: either withdraw did not succeed (we made no claim), or if it succeeded then the short token is no longer owned by maker
        // (ownerAfter != maker) OR owner query reverted which we approximate by ownerAfter == address(0).

        // Because we must end with exactly one assert, we encode the property as:
        // assert(!withdrew || ownerAfter != maker || ownerAfter == address(0xdead));
        // However ownerAfter==address(0) is used to indicate either reverted or zero address; include both possibilities.

        assert(!withdrew || ownerAfter != maker || ownerAfter == address(0) || ownerAfter == address(0xdead));
    }

    receive() external payable {}
}

