        });

        bytes memory signature = new bytes(0);
        uint256[] memory emptyFloorIds = new uint256[](0);

        bool filled = false;
        // Attempt to become owner of the short position by calling fillOrder where maker == address(this).
        // This is a top-level state-changing call on c as required.
        try c.fillOrder{value: amountETH}(order, signature, emptyFloorIds) returns (uint256 pid) {
            filled = true;
        } catch {
            filled = false;
        }

        bool withdrew = false;
        // If fill succeeded, this contract should own the short position token and can call withdraw.
        if (filled) {
            // Top-level state-changing call to withdraw
            try c.withdraw(order) {
                withdrew = true;
            } catch {
                withdrew = false;
            }
        }

        // Query orderHash and owner observable (view call allowed anywhere)
        bytes32 orderHash = c.hashOrder(order);

        address ownerAfter = address(0);
        if (filled) {
            // ownerOf may revert if token not minted; guard with try/catch (view call inside try is allowed as top-level try)
            try c.ownerOf(uint256(orderHash)) returns (address o) {
                ownerAfter = o;
            } catch {
                ownerAfter = address(0);
            }
        }

        // General rule asserted: if withdraw succeeded, then the short position token is no longer owned by the caller
        // (ownerAfter != address(this)) OR ownerOf reverted (ownerAfter == address(0) used to denote revert / not minted)
