contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take an order encoded by raw parameters; many fields can be arbitrary.
    // We take etherAmount to forward as msg.value when calling fillOrder. The test will attempt fillOrder
    // and then assert the general relation about ownership of minted position tokens and contract balance.
    function run(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 etherAmount
    ) public payable {
        // ensure this contract has enough balance if it will forward ETH
        if (etherAmount > 0) {
            require(address(this).balance >= etherAmount, "insufficient test balance");
        }

        // Read pre-state observables
        bytes32 orderHash = c.hashOrder(order);
        uint256 posIdMaker = uint256(orderHash);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 posIdTaker = uint256(opposite);

        address beforeOwnerMaker;
        address beforeOwnerTaker;

        // ownerOf will revert if not minted; catch with try/catch by reading via external calls
        bool makerMintedBefore = true;
        bool takerMintedBefore = true;
        try c.ownerOf(posIdMaker) returns (address a) { beforeOwnerMaker = a; } catch { makerMintedBefore = false; }
        try c.ownerOf(posIdTaker) returns (address a) { beforeOwnerTaker = a; } catch { takerMintedBefore = false; }

        uint256 balanceC_before = address(c).balance;

        // Try to perform the fillOrder call and capture whether it reverted
        bool reverted = false;
        try c.fillOrder{value: etherAmount}(order, signature, floorAssetTokenIds) returns (uint256 positionId) {
            // no-op, succeeded
        } catch {
            reverted = true;
        }

        uint256 balanceC_after = address(c).balance;

        // Read post-state owners
        bool makerMintedAfter = true;
        bool takerMintedAfter = true;
        address afterOwnerMaker;
        address afterOwnerTaker;
        try c.ownerOf(posIdMaker) returns (address a) { afterOwnerMaker = a; } catch { makerMintedAfter = false; }
        try c.ownerOf(posIdTaker) returns (address a) { afterOwnerTaker = a; } catch { takerMintedAfter = false; }

        // General rule (single assert):
        // If call succeeded then both positions became minted and their owners are order.maker and address(this) (the taker),
        // and the contract balance changed only by the forwarded etherAmount (i.e., delta equals either 0 or etherAmount depending on whether ETH was accepted by the contract).
        // If call reverted then nothing new was minted (no new owner) for either position compared to before.
        assert(
            (!reverted
                ? (
                    makerMintedAfter && takerMintedAfter &&
                    afterOwnerMaker == order.maker &&
                    // the taker (msg.sender in c) is this test contract; but per problem statement, the checker will call run from external address,
                    // however fillOrder is invoked with msg.sender = address(this) (InvMutTest) per instructions, so position minted to msg.sender
                    afterOwnerTaker == address(this) &&
                    // contract balance increased by at most etherAmount (it may transfer ETH out inside but net change must equal balanceC_after - before)
                    ((balanceC_after >= balanceC_before && balanceC_after - balanceC_before <= etherAmount) || (balanceC_before >= balanceC_after && balanceC_before - balanceC_after <= etherAmount))
                  )
                : (
                    // if reverted then neither position became minted newly
                    (makerMintedBefore == makerMintedAfter) && (takerMintedBefore == takerMintedAfter)
                  )
            )
        );
    }

    receive() external payable {}
}

