        bytes32 opp = c.hashOppositeOrder(order);
        uint256 takerPos = uint256(opp);

        // Probe owner before: if ownerOf reverts, mark as not minted before
        bool mintedBefore = true;
        address ownerBefore = address(0);
        try c.ownerOf(takerPos) returns (address o) {
            ownerBefore = o;
        } catch {
            mintedBefore = false;
        }

        // Attempt fillOrder and record whether it reverted
        bool reverted = false;
        try c.fillOrder{value: etherAmount}(order, signature, floorAssetTokenIds) returns (uint256) {
        } catch {
