        }

        // Assert the property in a single boolean expression:
        // If call succeeded -> taker position must be minted and owned by this contract.
        // If call reverted -> minted-ness did not change (either both not minted or owner equal before==after).
        assert(
            (!reverted
                ? (mintedAfter && ownerAfter == address(this))
                : (mintedAfter == mintedBefore && (mintedBefore == false || ownerAfter == ownerBefore))
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We check: when fillOrder is called for a short order (isLong==false),
    // the caller pays the premium to the maker: if premium is sent as native ETH and baseAsset==weth,
    // then the contract should accept msg.value equal to premium and forward WETH to maker; otherwise,
    // ERC20.safeTransferFrom should move premium from caller to maker. We can't inspect maker's external token balances,
    // but we can observe that fillOrder must not revert when the caller provides the correct payment and that
    // fillOrder reverts when msg.value doesn't match provided conditions. We encode this as: if msgValue==premium and
    // baseAsset equals c.weth() then fillOrder does not revert; if msgValue==0 and baseAsset is a contract address,
    // then fillOrder either does not revert (caller expected to have approved token) or reverts due to token transfer failure.
    // To make a general, provable invariant: when an order has isLong==false and isCall==false (short put),
    // fillOrder must revert if msg.value>0 and baseAsset != c.weth(), and must NOT revert solely due to ETH mismatch when
    // msg.value == 0 and baseAsset != c.weth() (i.e., it should accept ERC20 path). We therefore assert equivalence between
    // (baseAsset != weth) and (msgValue != order.premium) causing ETH-path revert. Concretely: if msgValue>0 then baseAsset must be weth, otherwise fillOrder reverts.

    // To satisfy the checker's requirements we expose parameters and perform the single state-mutating call at top-level.
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 msgValue
    ) public payable {
        require(expiration > block.timestamp, "precondition: expiration in future");
        // ensure this contract has enough ETH to send when msgValue>0
        if (msgValue > 0) {
            require(address(this).balance >= msgValue, "insufficient balance for ETH path");
        }

        // build minimal order: empty arrays for assets and whitelist
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // We will only consider short positions for this property (isLong == false)
        // The general rule concerns ETH usage vs weth address.
        require(!isLong, "test only for short positions");

        // attempt the call and capture whether it reverted
        bool reverted;
        bytes memory signature = "";
        uint256[] memory floorIds = new uint256[](0);
        try c.fillOrder{value: msgValue}(order, signature, floorIds) returns (uint256 positionId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule asserted:
        // If caller sent native ETH (msgValue > 0) then baseAsset must equal c.weth(), otherwise fillOrder must revert.
        // Conversely, if baseAsset == c.weth() and msgValue equals premium, the call should NOT revert solely due to ETH mismatch.
        // We can only observe revert boolean and public getter c.weth().
        address weth = c.weth();

        // Formulate the assertion as: (msgValue > 0 && baseAsset != weth) => reverted,
        // and (baseAsset == weth && msgValue == premium) => !reverted
        assert(((msgValue > 0 && baseAsset != weth) ? reverted : true) &&
               ((baseAsset == weth && msgValue == premium) ? !reverted : true));
    }

    receive() external payable {}
}
